    n = int(lines[0]); at=[]
    for l in lines[2:2+n]:
        q=l.split(); at.append((q[0], np.array(list(map(float,q[1:4])))))
    return at
b = read('opt3.xyz')
def d(i,j): return round(np.linalg.norm(b[i][1]-b[j][1]),3)
targets = {(0,1):2.05,(0,5):2.15,(3,2):2.15,(3,4):2.05,(0,56):2.18,(0,60):1.9,(0,65):2.32,(3,62):2.7,(3,63):1.9,(3,78):2.32,(0,3):3.3}
for k,v in targets.items():
    print(k, d(*k), "target", v)
